OUT=ROOT/'artifacts/final/satquery_v1';SOURCE=ROOT/'artifacts/training/phase3q/phase3q1_fusion_adaptation';MANIFEST=SOURCE/'phase3q1_training_manifest.json';DATA=Path(r'D:\Satquery_ai datasets\comparison\raw-1000');S1CK=ROOT/'artifacts/training/phase3p/phase3p1_sar_adaptation/phase3p1_sar_projector_final.pt';S2CK=ROOT/'artifacts/training/phase3o/phase3o12_run/phase3o12_projector_final.pt'
