 import torch
 OUT.mkdir(parents=True,exist_ok=True);print('PHASE3R START\nSATQUERY v1 ARCHITECTURE = S1 + S2 MULTIMODAL\nDATASET = BIGEARTHNET\nS1 = REQUIRED\nS2 = REQUIRED\nFUSION = CROMA JOINT\nS2 ONLY = BASELINE\nTEST ACCESS = 0\nJOINT PROJECTOR SHA = '+EXPECTED_JOINT_SHA,flush=True)
 man=json.loads(MANIFEST.read_text());rows=man['selection']['validation'];assert len(rows)==30 and Counter(r['task_type'] for r in rows)==Counter({'binary_qa':10,'multiple_choice_qa':10,'caption':10}) and man['test_access_count']==0
