 s1=S1SARProjector().eval();s1.load_state_dict(torch.load(S1CK,map_location='cpu',weights_only=True)['state_dict']);s10=module_fingerprint(s1);s2=S2MultispectralProjector().eval();s2.load_state_dict(torch.load(S2CK,map_location='cpu',weights_only=True)['state_dict']);s20=module_fingerprint(s2)
 controller=SatQueryV1Controller();samples={x.patch_id:x for x in discover_samples(DATA,strict=True)};prepared={r['image_id']:load_sample(samples[r['image_id']]) for r in rows};first=prepared[rows[0]['image_id']]
 # Explicit failure tests before loading the normal route.
